from contextlib import contextmanager
from inspect import currentframe
from logging import Logger
from os.path import basename, join

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import SERVER_HOST
from ta_logcollector.utils.common import collect_swconfig_from_enb

logger = Logger("LC")


def start():
    """Method does nothing, this plugin does not require activation."""
    logger.info("Inside {} start".format(basename(__file__)))


def stop(log_dir):
    """
    Method responsible for storing swconfig file from enb

    :param log_dir: string containing the destination where to save swconfig file
    """
    logger.info("Inside {} before stop".format(basename(__file__)))
    enb_log_file = join(log_dir, "swconfig_{}.txt".format(SERVER_HOST))
    collect_swconfig_from_enb(logger, enb_log_file)
    logger.info("Inside {} after stop".format(basename(__file__)))


@contextmanager
def swconfig(log_host, log_port, **kwargs):
    # type: (str, int, dict) -> None
    """
    Plugin for collecting swconfig file from enb. When it starts it does nothing but waits
    for stop action. Then it downloads file from enb and saves it at the destination
    provided by the user.

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(currentframe().f_code.co_name, SERVER_HOST))
    log_dir = kwargs.pop("log_dir")
    try:
        start()
        yield
    finally:
        stop(log_dir)
